const label=s=>statusNames[s]||({RETAIL:'零售毛利',LEVEL:'级差收益',PEER:'同级分红',GROUP_FAILED:'拼团失败自动退款',FORMING:'待成团',FORMED:'已成团',INVITE_REWARD:'邀请订单奖励',INVITE_COST:'商城邀请奖励支出',REFUND_INVITE_REWARD:'邀请奖励冲正',REFUND_INVITE_COST:'邀请奖励支出冲正',PROMOTION_COST:'商城优惠承担',REFUND_PROMOTION_COST:'优惠成本冲正',PEER_COST:'商城分红支出',REFUND_RETAIL:'零售收益冲正',REFUND_LEVEL:'级差收益冲正',REFUND_PEER:'分红收入冲正',REFUND_PEER_COST:'分红支出冲正',PAYOUT:'提现付款',ORDER_REWARD:'购物赠送',ORDER_USE:'订单抵扣',REFUND_RETURN:'退款返还',REFUND_RECLAIM:'退款追回',TRANSFER_IN:'转赠收入',TRANSFER_OUT:'转赠支出',CHECKIN:'每日签到',REDEMPTION:'积分兑换',REVIEW_REWARD:'评价赠送',EXPIRE:'积分到期',RETURN_EXPIRED:'返还积分已超过原有效期',DEBT_OFFSET:'抵扣待追回积分',SCHEDULED:'待生效',APPLIED:'已生效'}[s])||s
function uuid(){return 'req-'+Date.now().toString(36)+'-'+Math.random().toString(36).slice(2,14)}
export function request(path,data,method='GET',idempotency){return new Promise((resolve,reject)=>uni.request({url:(import.meta.env.VITE_HEXU_API||'')+path,method,data,header:{'Content-Type':'application/json',...(backend.token?{Authorization:'Bearer '+backend.token}:{}),...(idempotency?{'Idempotency-Key':idempotency}:{})},success:r=>{if(r.statusCode>=200&&r.statusCode<300&&r.data?.code===200)resolve(r.data.data);else reject(new Error(r.data?.msg||'接口请求失败'))},fail:()=>reject(new Error('无法连接业务服务，请检查后台是否启动'))}))}
export async function apiCommand(operation,data={},management=false,key){
 const body={shopId:backend.shopId,...data};const signature=JSON.stringify([backend.member?.id,management,operation,body]);let hash=2166136261;for(const ch of signature)hash=Math.imul(hash^ch.charCodeAt(0),16777619);
 const cacheKey='hexu-retry-'+(hash>>>0);const idempotency=key||uni.getStorageSync(cacheKey)||uuid();uni.setStorageSync(cacheKey,idempotency);
 const result=await request('/hexu/app/'+(management?'management/':'commands/')+operation,body,'POST',idempotency);uni.removeStorageSync(cacheKey);return result;
}
export async function connect(){if(bootPromise)return bootPromise;bootPromise=(async()=>{backend.loading=true;try{const entry=entryOptions();let memberId=201,shopId=Number(entry.shop)||Number(uni.getStorageSync('hexu-shop-id'))||2;if(entry.invite)state.invite=entry.invite;if(entry.group)state.selectedGroup=entry.group;
 // #ifdef H5
 const params=new URLSearchParams(location.search);const hashQuery=location.hash.split('?')[1];const hp=new URLSearchParams(hashQuery||'');memberId=Number(params.get('member')||hp.get('member')||uni.getStorageSync('hexu-member-id'))||201;shopId=Number(params.get('shop')||hp.get('shop'))||shopId;state.selectedGroup=params.get('group')||hp.get('group')||state.selectedGroup||'';state.invite=params.get('invite')||hp.get('invite')||state.invite||'';
 // #endif
 backend.shopId=shopId;uni.setStorageSync('hexu-shop-id',shopId);backend.token=uni.getStorageSync('hexu-api-token')||'';
 if(import.meta.env.DEV){const r=await request('/__hexu_dev/login',{memberId},'POST');backend.token=r.token;uni.setStorageSync('hexu-api-token',r.token);uni.setStorageSync('hexu-member-id',memberId)}
 if(!backend.token)throw new Error('请先通过微信授权登录');await refresh();backend.ready=true;backend.error='';return true}catch(e){backend.error=e.message;toast(e.message);return false}finally{backend.loading=false;bootPromise=null}})();return bootPromise}
function normalizedOrder(o){return {...o,rawStatus:o.status,status:o.status==='PAID'&&o.group?.status==='FORMING'?'待成团':label(o.status),items:(o.items||[]).map(l=>({...l,lineId:l.id,id:l.sku_id,qty:l.qty,unitPrice:l.unit_price})),total:Number(o.total),subtotal:Number(o.subtotal)}}
export async function refresh(){const data=await request('/hexu/app/bootstrap',{shopId:backend.shopId});backend.member=data.member;backend.shopInfo=data.shop;backend.checkinRewards=data.checkinRewards;backend.agent=data.agent;backend.account=data.account;state.shop=data.shop.name;state.points=Number(data.account.platformPoints.available||0);state.shopPoints=Number(data.account.shopPoints.available||0);state.balance=Number(data.account.wallet.available||0);state.addresses=data.addresses.filter(d=>d.status==='ACTIVE').map(d=>({...d.body,serverId:d.id}));
 products.splice(0,products.length,...data.products.map(p=>({...p,price:Number(p.price),agent:Number(p.price),stock:p.stock,desc:p.spec})));
 if(state.lastWithdrawal){const latest=data.account.withdrawals?.find(w=>w.id===state.lastWithdrawal.id);if(latest)state.lastWithdrawal={...latest,cents:latest.amount};}state.orders=data.orders.map(normalizedOrder);state.notifications=data.notifications.map(n=>({id:n.id,message:n.title,body:n.body_text||n.title,event:n.event_type,time:n.created_at,reference:n.reference_id,read:!!n.is_read}));state.signedIn=true;
 const [shops,coupons]=await Promise.all([request('/hexu/app/shops'),request('/hexu/app/coupons',{shopId:backend.shopId})]);backend.shops=shops;backend.coupons=coupons;
 if(backend.refund&&Number(backend.refund.member_id)===Number(backend.member.id))backend.refund=data.account.refunds.find(r=>r.id===backend.refund.id)||null;
 const carts=data.cart.filter(d=>d.status==='ACTIVE');if(carts.length){const c=carts[0];state.cart=(c.body.items||[]).map(l=>({...l,selected:l.selected!==false}));state.serverCartId=c.id}else{state.cart=[];state.serverCartId=null}
 const favorite=data.favorites.filter(d=>d.status==='ACTIVE')[0];state.favorites=favorite?.body?.ids||[];state.serverFavoriteId=favorite?.id;state.serverHydrated=true;persist();
 if(state.activeOrder){try{const order=normalizedOrder(await request('/hexu/app/orders/'+state.activeOrder));backend.activeOrder=order;const i=state.orders.findIndex(x=>x.id===order.id);if(i>=0)state.orders[i]=order}catch{backend.activeOrder=null}}
}
let cartWrite=Promise.resolve()
export function syncCart(){if(!backend.ready)return Promise.resolve();const data={kind:'cart',shopId:backend.shopId,id:state.serverCartId,items:JSON.parse(JSON.stringify(state.cart))};cartWrite=cartWrite.catch(()=>{}).then(async()=>{const d=await apiCommand('document-save',data);if(backend.shopId===data.shopId){state.serverCartId=d.id;persist()}});return cartWrite}
export async function syncFavorites(){if(!backend.ready)return;const d=await apiCommand('document-save',{kind:'favorite',id:state.serverFavoriteId,ids:state.favorites});state.serverFavoriteId=d.id;persist()}
export async function uploadAttachment(filePath,purpose='IDENTITY'){if(!backend.ready&&!(await connect()))throw new Error('请先登录');backend.uploadingCount=(backend.uploadingCount||0)+1;return new Promise((resolve,reject)=>uni.uploadFile({url:(import.meta.env.VITE_HEXU_API||'')+'/hexu/app/attachments',filePath,name:'file',formData:{shopId:backend.shopId,purpose},header:{Authorization:'Bearer '+backend.token},success:r=>{try{const body=JSON.parse(r.data);if(body.code!==200)throw new Error(body.msg||'上传失败');resolve(body.data)}catch(e){reject(e)}},fail:()=>reject(new Error('图片上传失败，请重试'))})).finally(()=>backend.uploadingCount=Math.max(0,(backend.uploadingCount||1)-1))}
